	"github.com/cloudwego/kitex/pkg/utils"
	"github.com/cloudwego/kitex/transport"
)

// UnaryOption is an option specific to unary RPC calls
type UnaryOption struct {
	Option
}

// StreamOption is an option specific to streaming RPC calls
type StreamOption struct {
	Option
}

// TTHeaderStreamingOption is an option specific to TTHeader streaming protocol
type TTHeaderStreamingOption struct {
	Option
}

// Unary Option Constructors

// WithUnaryMiddleware adds middleware for unary client calls
func WithUnaryMiddleware(mw endpoint.Middleware) UnaryOption {
	return UnaryOption{
		Option: WithMiddleware(mw),
	}
}

// WithUnaryTimeout sets the timeout for unary RPC calls
func WithUnaryTimeout(timeout time.Duration) UnaryOption {
	return UnaryOption{
		Option: Option{F: func(o *client.Options, di *utils.Slice) {
			di.Push(fmt.Sprintf("WithUnaryTimeout(%s)", timeout))
			rpcinfo.AsMutableRPCConfig(o.Configs).SetRPCTimeout(timeout)
		}},
	}
}

// WithUnaryRetry enables retry for unary calls
func WithUnaryRetry(maxRetries int) UnaryOption {
	return UnaryOption{
		Option: Option{F: func(o *client.Options, di *utils.Slice) {
			di.Push(fmt.Sprintf("WithUnaryRetry(%d)", maxRetries))
			// Store retry config in options
			o.RetryConfig = &client.RetryConfig{
				MaxRetries: maxRetries,
			}
		}},
	}
}

// Stream Option Constructors

// WithStreamMiddleware adds middleware for streaming client calls
func WithStreamMiddleware(mw endpoint.Middleware) StreamOption {
	return StreamOption{
		Option: WithMiddleware(mw),
	}
}

// WithStreamTimeout sets the timeout for streaming RPC calls
func WithStreamTimeout(timeout time.Duration) StreamOption {
	return StreamOption{
		Option: Option{F: func(o *client.Options, di *utils.Slice) {
			di.Push(fmt.Sprintf("WithStreamTimeout(%s)", timeout))
			rpcinfo.AsMutableRPCConfig(o.Configs).SetRPCTimeout(timeout)
		}},
	}
}

// WithStreamBufferSize sets the buffer size for streaming calls
func WithStreamBufferSize(size int) StreamOption {
	return StreamOption{
		Option: Option{F: func(o *client.Options, di *utils.Slice) {
			di.Push(fmt.Sprintf("WithStreamBufferSize(%d)", size))
			// Store stream buffer size in options
			if o.StreamOptions == nil {
				o.StreamOptions = make(map[string]interface{})
			}
			o.StreamOptions["buffer_size"] = size
		}},
	}
}

// WithStreamMaxConcurrency sets maximum concurrent streams
func WithStreamMaxConcurrency(max int) StreamOption {
	return StreamOption{
		Option: Option{F: func(o *client.Options, di *utils.Slice) {
			di.Push(fmt.Sprintf("WithStreamMaxConcurrency(%d)", max))
			if o.StreamOptions == nil {
				o.StreamOptions = make(map[string]interface{})
			}
			o.StreamOptions["max_concurrency"] = max
		}},
	}
}

// WithStreamFlowControl enables flow control for streaming
func WithStreamFlowControl(enabled bool) StreamOption {
	return StreamOption{
		Option: Option{F: func(o *client.Options, di *utils.Slice) {
			di.Push(fmt.Sprintf("WithStreamFlowControl(%v)", enabled))
			if o.StreamOptions == nil {
				o.StreamOptions = make(map[string]interface{})
			}
			o.StreamOptions["flow_control"] = enabled
		}},
	}
}

// TTHeaderStreaming Option Constructors

// WithTTHeaderStreamingProtocol sets the transport protocol to TTHeaderStreaming
func WithTTHeaderStreamingProtocol() TTHeaderStreamingOption {
	return TTHeaderStreamingOption{
		Option: WithTransportProtocol(transport.TTHeaderStreaming),
	}
}

// WithTTHeaderStreamingMiddleware adds middleware for TTHeader streaming calls
func WithTTHeaderStreamingMiddleware(mw endpoint.Middleware) TTHeaderStreamingOption {
	return TTHeaderStreamingOption{
		Option: WithMiddleware(mw),
	}
}

// WithTTHeaderStreamingTimeout sets the timeout for TTHeader streaming RPC calls
func WithTTHeaderStreamingTimeout(timeout time.Duration) TTHeaderStreamingOption {
	return TTHeaderStreamingOption{
		Option: Option{F: func(o *client.Options, di *utils.Slice) {
			di.Push(fmt.Sprintf("WithTTHeaderStreamingTimeout(%s)", timeout))
			rpcinfo.AsMutableRPCConfig(o.Configs).SetRPCTimeout(timeout)
		}},
	}
}

// WithTTHeaderStreamingMaxFrameSize sets max frame size for TTHeader streaming
func WithTTHeaderStreamingMaxFrameSize(size int) TTHeaderStreamingOption {
	return TTHeaderStreamingOption{
		Option: Option{F: func(o *client.Options, di *utils.Slice) {
