// ConnectionInfo contains diagnostic information about a connection
type ConnectionInfo struct {
	Address    string
	IsActive   bool
	StreamCount int32
}

// PoolDump contains diagnostic information about the connection pool
type PoolDump struct {
	RemoteService string
	PoolSize      uint32
	Connections   []ConnectionInfo
}

// Dump returns diagnostic information about the connection pool state
func (p *connPool) Dump() *PoolDump {
	dump := &PoolDump{
		RemoteService: p.remoteService,
		PoolSize:      p.size,
		Connections:   make([]ConnectionInfo, 0),
	}

	p.conns.Range(func(key, value interface{}) bool {
		address := key.(string)
		trans := value.(*transports)
		for i := 0; i < int(trans.size); i++ {
			cliTransport := trans.cliTransports[i]
			if cliTransport != nil {
				info := ConnectionInfo{
					Address:  address,
					IsActive: cliTransport.(grpc.IsActive).IsActive(),
				}
				// Try to get stream count if available
				if counter, ok := cliTransport.(interface{ StreamCount() int32 }); ok {
					info.StreamCount = counter.StreamCount()
				}
				dump.Connections = append(dump.Connections, info)
			}
		}
		return true
	})

	return dump
}

