// connError represents an HTTP/2 ConnectionError error code, along
// with a string (for debugging) explaining why.
//
// Errors of this type are only returned by the frame parser functions
// and converted into ConnectionError(Code), after stashing away
// the Reason into the Framer's errDetail field, accessible via
// the (*Framer).ErrorDetail method.
type connError struct {
	Code      http2.ErrCode // the ConnectionError error code
	Reason    string        // additional reason
	Timestamp time.Time     // when the error occurred
	StreamID  uint32        // associated stream ID if applicable
	FrameType string        // frame type that caused the error
}

func (e connError) Error() string {
	msg := fmt.Sprintf("http2: connection error: %v: %v", e.Code, e.Reason)
	if e.StreamID != 0 {
		msg += fmt.Sprintf(" (stream_id=%d)", e.StreamID)
	}
	if e.FrameType != "" {
		msg += fmt.Sprintf(" (frame_type=%s)", e.FrameType)
	}
	if !e.Timestamp.IsZero() {
		msg += fmt.Sprintf(" (timestamp=%s)", e.Timestamp.Format(time.RFC3339Nano))
	}
	return msg
}

// NewConnError creates a new connError with timestamp
func NewConnError(code http2.ErrCode, reason string) connError {
	return connError{
		Code:      code,
		Reason:    reason,
		Timestamp: time.Now(),
	}
}

// NewConnErrorWithContext creates a new connError with full context
func NewConnErrorWithContext(code http2.ErrCode, reason string, streamID uint32, frameType string) connError {
	return connError{
		Code:      code,
		Reason:    reason,
		Timestamp: time.Now(),
		StreamID:  streamID,
		FrameType: frameType,
	}
}

